WITH p AS (SELECT ID,SEX FROM Patient WHERE Birthday IS NOT NULL AND (strftime('%Y','now')-strftime('%Y',Birthday))>55),
x AS (SELECT p.ID,p.SEX,MAX(l.PT>=14) ab FROM p JOIN Laboratory l ON l.ID=p.ID WHERE l.PT IS NOT NULL GROUP BY p.ID)
SELECT 100.0*SUM(SEX='F' AND ab=1)/COUNT(*) AS pct FROM x;

WITH old AS (
  SELECT c.client_id, d.A11 FROM client c JOIN district d ON d.district_id=c.district_id
  WHERE c.gender='F' AND c.birth_date=(SELECT MIN(birth_date) FROM client WHERE gender='F')
), low AS (SELECT MIN(A11) m FROM old)
SELECT di.account_id, (SELECT MAX(A11) FROM district) - low.m AS gap
FROM old JOIN low ON old.A11=low.m JOIN disp di ON di.client_id=old.client_id;

SELECT s.School, s.DOCType FROM frpm f JOIN schools s ON s.CDSCode=f.CDSCode
WHERE f.`Charter Funding Type`='Locally funded'
AND f.`Enrollment (K-12)`-f.`Enrollment (Ages 5-17)` > (SELECT AVG(`Enrollment (K-12)`-`Enrollment (Ages 5-17)`) FROM frpm WHERE `Charter Funding Type`='Locally funded');
